//! The application icon and the tray icons.
//!
//! All artwork comes from resources compiled into the executable (`assets/allblack11.rc`),
//! generated by `assets/brand/brand_icon.py`. Nothing is drawn at run time.
//!
//! - resource 1: the full-color app icon (window class, taskbar, shortcuts, installer);
//! - resources 10 to 13: single-color tray marks. 10/11 are white (dark taskbar) and 12/13 are
//!   near-black (light taskbar); the odd ids are the "off or paused" outline of the same mark.
//!   State is a shape difference (filled moon or outline), never color alone.

use windows_sys::core::PCWSTR;
use windows_sys::Win32::Foundation::HINSTANCE;
use windows_sys::Win32::Graphics::Gdi::GetSysColor;
use windows_sys::Win32::System::LibraryLoader::{GetProcAddress, LoadLibraryW};
use windows_sys::Win32::UI::WindowsAndMessaging::{
    GetSystemMetrics, LoadImageW, HICON, IMAGE_ICON, LR_SHARED, SM_CXICON, SM_CXSMICON,
};

use super::registry;
use super::wide::{pcw, to_wide};

type LoadIconWithScaleDown =
    unsafe extern "system" fn(HINSTANCE, PCWSTR, i32, i32, *mut HICON) -> i32;

pub const APP_ICON: usize = 1;
const TRAY_WHITE_ON: usize = 10;
const TRAY_BLACK_ON: usize = 12;

/// Whether the notification area is dark. It follows the system theme; under a contrast theme
/// it is the system window color.
pub fn taskbar_is_dark(high_contrast: bool) -> bool {
    if high_contrast {
        // COLOR_WINDOW = 5. Perceived brightness of the window color decides white or black.
        let color = unsafe { GetSysColor(5) };
        let (r, g, b) = (color & 0xFF, (color >> 8) & 0xFF, (color >> 16) & 0xFF);
        (r * 299 + g * 587 + b * 114) / 1000 < 128
    } else {
        registry::system_prefers_dark().unwrap_or(true)
    }
}

/// The two tray icons for this taskbar: (styling on, off or paused). The caller owns both and
/// must `DestroyIcon` them. Null when the resource is missing.
pub fn load_tray_icons(instance: HINSTANCE, dark_taskbar: bool) -> (HICON, HICON) {
    let size = unsafe { GetSystemMetrics(SM_CXSMICON) }.clamp(16, 64);
    let base = if dark_taskbar {
        TRAY_WHITE_ON
    } else {
        TRAY_BLACK_ON
    };
    (
        load_resource(instance, base, size),
        load_resource(instance, base + 1, size),
    )
}

/// An icon resource at `size` pixels (owned: destroy it), picking the nearest tuned size.
pub fn load_resource(instance: HINSTANCE, id: usize, size: i32) -> HICON {
    if let Some(icon) = load_scaled(instance, id, size) {
        return icon;
    }
    let loaded = unsafe { LoadImageW(instance, id as PCWSTR, IMAGE_ICON, size, size, 0) };
    loaded as HICON
}

/// The app icon for a window class: big (`SM_CXICON`) or small (`SM_CXSMICON`). Shared by the
/// system, so it is never destroyed.
pub fn window_icon(instance: HINSTANCE, big: bool) -> HICON {
    let size = unsafe { GetSystemMetrics(if big { SM_CXICON } else { SM_CXSMICON }) }.max(16);
    unsafe {
        LoadImageW(
            instance,
            APP_ICON as PCWSTR,
            IMAGE_ICON,
            size,
            size,
            LR_SHARED,
        ) as HICON
    }
}

fn load_scaled(instance: HINSTANCE, id: usize, size: i32) -> Option<HICON> {
    let module_name = to_wide("comctl32.dll");
    let module = unsafe { LoadLibraryW(pcw(&module_name)) };
    if module.is_null() {
        return None;
    }
    let proc_addr = unsafe { GetProcAddress(module, b"LoadIconWithScaleDown\0".as_ptr())? };
    let load: LoadIconWithScaleDown = unsafe { std::mem::transmute(proc_addr as usize) };
    let mut icon: HICON = std::ptr::null_mut();
    let hr = unsafe { load(instance, id as PCWSTR, size, size, &mut icon) };
    if hr >= 0 && !icon.is_null() {
        Some(icon)
    } else {
        None
    }
}
